#include "../Plugin.cpp"
#include <iostream>
#include <random>
#include <stdexcept>
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
void set(Processor& p,const char* id,float value){auto* a=p.state.getParameter(id);a->setValueNotifyingHost(a->convertTo0to1(value));}
int main(){juce::ScopedJuceInitialiser_GUI gui;try{Processor p;require(p.state.getRawParameterValue("ratio")->load()==2,"fresh ratio 12:1");set(p,"ratio",0);p.setCurrentProgram(0);require(p.state.getRawParameterValue("ratio")->load()==2,"Default factory program 12:1");set(p,"ratio",3);juce::MemoryBlock saved;p.getStateInformation(saved);Processor restored;restored.setStateInformation(saved.getData(),int(saved.getSize()));require(restored.state.getRawParameterValue("ratio")->load()==3,"saved 20:1 retained");{std::unique_ptr<juce::AudioProcessorEditor> e(p.createEditor());require(e->getWidth()==430&&e->getHeight()==270,"GUI dimensions");}std::mt19937 rng(1176);std::uniform_real_distribution<float> noise(-.2f,.2f);juce::MidiBuffer midi;double maximum=0;
for(int rate:{44100,48000}){
 for(int ratio=0;ratio<5;ratio++)for(float input:{0.f,20.f})for(float output:{-15.f,15.f})for(float attack:{0.f,10.f})for(float release:{0.f,10.f}){set(p,"ratio",float(ratio));set(p,"input",input);set(p,"output",output);set(p,"attack",attack);set(p,"release",release);set(p,"bypass",0);p.prepareToPlay(rate,257);juce::AudioBuffer<float>b(2,257);for(int k=0;k<10;k++){for(int i=0;i<257;i++){float x=noise(rng);b.setSample(0,i,x);b.setSample(1,i,x);}p.processBlock(b,midi);for(int i=0;i<257;i++){float y=b.getSample(0,i);require(std::isfinite(y)&&fabs(y)<1000,"finite extremes");require(y==b.getSample(1,i),"stereo equality");maximum=std::max(maximum,double(fabs(y)));}}}
 Processor mono,stereo;auto layout=mono.getBusesLayout();layout.inputBuses.set(0,juce::AudioChannelSet::mono());layout.outputBuses.set(0,juce::AudioChannelSet::mono());require(mono.setBusesLayout(layout),"mono layout");mono.prepareToPlay(rate,257);stereo.prepareToPlay(rate,257);for(int k=0;k<25;k++){juce::AudioBuffer<float>a(1,257),b(2,257);for(int i=0;i<257;i++){float x=noise(rng);a.setSample(0,i,x);b.setSample(0,i,x);b.setSample(1,i,x);}mono.processBlock(a,midi);stereo.processBlock(b,midi);for(int i=0;i<257;i++)require(a.getSample(0,i)==b.getSample(0,i),"mono/stereo consistency");}
 Processor automation;automation.prepareToPlay(rate,257);juce::AudioBuffer<float>a(2,257);for(int k=0;k<300;k++){if(k%4==0)for(auto* param:automation.getParameters())param->setValueNotifyingHost(float(rng()%1001)/1000);for(int i=0;i<257;i++){float x=noise(rng);a.setSample(0,i,x);a.setSample(1,i,x);}automation.processBlock(a,midi);for(int c=0;c<2;c++)for(int i=0;i<257;i++)require(std::isfinite(a.getSample(c,i)),"finite automation");}
 Processor tail;tail.prepareToPlay(rate,257);juce::AudioBuffer<float>b(2,257);b.clear();b.setSample(0,0,.5f);b.setSample(1,0,.5f);tail.processBlock(b,midi);for(int k=0;k<int(rate/257)+1;k++){b.clear();tail.processBlock(b,midi);}for(int i=0;i<257;i++)require(fabs(b.getSample(0,i))<1e-6,"filter tail decay");std::cout<<"PASS "<<rate<<" Hz: parameter extremes, stereo symmetry, mono consistency, finite automation, decaying filter tail"<<std::endl;
}std::cout<<"PASS fresh/Default 12:1, saved-ratio recall, unchanged 430x270 GUI. Extreme-test peak="<<maximum<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
